tool_input.command:
node --test test/ 2>&1 | tail -8 && node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
const lines = [];
const out = (l) => lines.push(l);
for (const [u, off] of [['ist', 330], ['nyc', -300]]) {
  handle({ method: 'POST', path: '/reminders', body: { userId: u, text: 'x', at: '2026-03-01T09:00', tzOffsetMin: off } });
}
// IST 09:00 = 03:30Z ; NYC 09:00 = 14:00Z
for (const t of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z','2026-03-01T14:00:00Z','2026-03-01T19:00:00Z']) {
  await tick(Date.parse(t), { formatter: 'format', out });
  console.log(t, '->', JSON.stringify(lines.splice(0)));
}
const r = handle({ method: 'POST', path: '/reminders', body: { userId: 'bad', text: 'y', at: '2026-03-01T09:00:00' } });
console.log('seconds in at ->', r.status, r.body.due_ms);
"
